lemma IsENet.image_of_lipschitz [DecidableEq B] {L : ℝ} (hL : 0 ≤ L) {f : A → B}
    (hf : ∀ x y : A, dist (f x) (f y) ≤ L * dist x y)
    {t : Finset A} {eps : ℝ} {s : Set A}
    (hnet : IsENet t eps s) :
    IsENet (t.image f) (L * eps) (f '' s)

lemma closedBall_half_disjoint {E : Type*} [PseudoMetricSpace E] {x y : E} {eps : ℝ}
    (_heps : 0 ≤ eps) (hsep : eps < dist x y) :
    Disjoint (Metric.closedBall x (eps / 2)) (Metric.closedBall y (eps / 2))

lemma exists_finset_isENet_of_totallyBounded {eps : ℝ} {s : Set A}
    (heps : 0 < eps) (hs : TotallyBounded s) :
    ∃ t : Finset A, IsENet t eps s

lemma exists_finset_isENet_subset_of_totallyBounded {eps : ℝ} {s : Set A}
    (heps : 0 < eps) (hs : TotallyBounded s) :
    ∃ t : Finset A, IsENet t eps s ∧ (t : Set A) ⊆ s

lemma exists_optimal_enet {eps : ℝ} {s : Set A}
    (heps : 0 < eps) (hs : TotallyBounded s) :
    ∃ t : Finset A, IsENet t eps s ∧ (t.card : WithTop ℕ) = coveringNumber eps s

lemma eLpNorm_norm_add_le {α : Type*} [MeasurableSpace α] {μ : Measure α}
    {E : Type*} [NormedAddCommGroup E] {f g : α → E}
    (hf : AEStronglyMeasurable f μ) (hg : AEStronglyMeasurable g μ) :
    eLpNorm (fun x => ‖f x‖ + ‖g x‖) 2 μ ≤ eLpNorm f 2 μ + eLpNorm g 2 μ

lemma exists_lt_of_tendsto_nhdsWithin_right {f : ℝ → ℝ≥0∞} {b : ℝ≥0∞}
    (hf : Tendsto f (nhdsWithin 0 (Set.Ioi 0)) (nhds 0)) (hb : 0 < b) :
    ∃ ε : ℝ, 0 < ε ∧ f ε < b

theorem mollify_dist_le_of_lipschitz {f : E n → ℝ} {L : ℝ≥0} {ε : ℝ}
    (hε : 0 < ε) (hf : LipschitzWith L f) (x : E n) :
    dist (mollify ε f x) (f x) ≤ L * ∫ z : E n, ‖z‖ * stdMollifierPi n ε z

theorem mollify_dist_le_of_lipschitz' {f : E n → ℝ} {L : ℝ≥0} {ε : ℝ}
    (hε : 0 < ε) (hf : LipschitzWith L f) (x : E n) :
    dist (mollify ε f x) (f x) ≤ L * ε * Real.sqrt n

lemma mollify_smooth_of_lipschitz {f : E n → ℝ} {L : ℝ≥0}
    (hf : LipschitzWith L f) {ε : ℝ} (hε : 0 < ε) :
    ContDiff ℝ (⊤ : ℕ∞) (mollify ε f)

theorem mollify_tendsto_of_lipschitz {f : E n → ℝ} {L : ℝ≥0}
    (hf : LipschitzWith L f) (x : E n) :
    Filter.Tendsto (fun ε => mollify ε f x) (nhdsWithin 0 (Set.Ioi 0)) (nhds (f x))

lemma sup_norm_fderiv_le_of_mollify_lipschitz {f : E n → ℝ} {L : ℝ≥0} {ε : ℝ}
    (hε : 0 < ε) (hf : LipschitzWith L f) (x : E n) :
    ‖fderiv ℝ (mollify ε f) x‖ ≤ L

lemma eLpNorm_tendsto_zero_of_tendstoUniformly_general {n : ℕ} {μ : Measure (E n)}
    {f : ℕ → E n → ℝ} {g : E n → ℝ}
    {s : Set (E n)} (hμ : μ s < ⊤)
    (hf_zero : ∀ i x, x ∉ s → f i x = 0) (hg_zero : ∀ x, x ∉ s → g x = 0)
    (h_unif : TendstoUniformly f g Filter.atTop) :
    Filter.Tendsto (fun i => eLpNorm (f i - g) 2 μ) Filter.atTop (nhds 0)

lemma mollify_tendsto_uniformly_on_compact {n : ℕ} {g : E n → ℝ} {K : Set (E n)}
    (hK : IsCompact K) (hg_cont : Continuous g) :
    TendstoUniformlyOn (fun ε => mollify ε g) g (nhdsWithin 0 (Set.Ioi 0)) K

lemma bounded_hansonWright_cgf_constant_le {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) {K C : ℝ}
    (hC_bound : 2 * entrywiseL1Norm A ^ 2 ≤ C * frobeniusNorm A ^ 2) (l : ℝ) :
    2 * (K ^ 2 * entrywiseL1Norm A) ^ 2 * l ^ 2 ≤
      C * l ^ 2 * K ^ 4 * frobeniusNorm A ^ 2

lemma centered_sq_cgf_le_of_hasSubgaussianMGF_of_le {μ : Measure Ω}
    [IsProbabilityMeasure μ] {X : Ω → ℝ} {c : ℝ≥0}
    (h : HasSubgaussianMGF X c μ) {θ C0 : ℝ}
    (hC0 : 0 < C0) (hc_le : (c : ℝ) ≤ C0)
    (hθ_abs : |θ| * C0 * exp 1 ≤ 1 / 2) :
    cgf (fun ω => X ω ^ 2 - ∫ ω, X ω ^ 2 ∂μ) μ θ ≤
      2 * exp 1 * (θ * C0 * exp 1) ^ 2

lemma hasSubgaussianMGF_finset_sum_const_mul_of_iIndepFun {ι : Type*} {μ : Measure Ω}
    {X : ι → Ω → ℝ} (h_indep : iIndepFun X μ) {c : ι → ℝ≥0}
    {s : Finset ι} (h_subG : ∀ i ∈ s, HasSubgaussianMGF (X i) (c i) μ)
