lemma iIndepFun.integrable_exp_mul_sum₀ {ι : Type*} {μ : Measure Ω} [IsFiniteMeasure μ]
    {X : ι → Ω → ℝ}
    (h_indep : iIndepFun X μ) (h_meas : ∀ i, AEMeasurable (X i) μ)
    {s : Finset ι} {t : ℝ}
    (h_int : ∀ i ∈ s, Integrable (fun ω => exp (t * X i ω)) μ) :
