    (hθ_star : l1norm θ_star ≤ R) (hh : h ∈ l1ShiftedClass d R θ_star)
    (hα_pos : 0 ≤ α) (hα_le : α ≤ 1) :
    α • h ∈ l1ShiftedClass d R θ_star

lemma zero_mem_l1ShiftedClass {R : ℝ} {θ_star : EuclideanSpace ℝ (Fin d)}
    (hθ_star : l1norm θ_star ≤ R) :
    (0 : (EuclideanSpace ℝ (Fin d)) → ℝ) ∈ l1ShiftedClass d R θ_star

lemma add_mem_linearPredictorClass {f g : (EuclideanSpace ℝ (Fin d)) → ℝ}
    (hf : f ∈ linearPredictorClass d) (hg : g ∈ linearPredictorClass d) :
    f + g ∈ linearPredictorClass d

lemma neg_mem_linearPredictorClass {f : (EuclideanSpace ℝ (Fin d)) → ℝ}
